using System.Reflection; using Microsoft.Extensions.Configuration; using Microsoft.Extensions.DependencyInjection; using MicroServiceSystem.BuildingBlocks.Application.Extensions;
namespace MicroServiceSystem.Services.Logging.Application; public static class LoggingApplicationExtensions { public static readonly Assembly ApplicationAssembly=typeof(LoggingApplicationExtensions).Assembly; public static IServiceCollection AddLoggingApplication(this IServiceCollection services,IConfiguration configuration){services.AddApplicationBuildingBlock(configuration,ApplicationAssembly);return services;} }
